// Storefront texts the scripts need, per language, from the ifcvo-i18n-<lang>.json
// assets (generated by build-extension.mjs from locales/). The Liquid only marks an
// element with data-i18n="<group>" (→ data-labels), plus data-i18n-<attr>="<group>"
// on the same element for more (→ data-<attr>); this module fills those attributes before any block script that
// imports it runs (top-level await). Shopify caps each extension at 100 KB of Liquid
// and 15 KB per locale file, so these texts live in assets instead.
// No fetch when the page has no such element; a failed fetch leaves each script on
// its English defaults.

// LANGS:start (written by build-extension.mjs)
export const LANGS = ["ca","de","en","es","fr","it","ja","pt-BR","pt-PT","th","zh-CN"]
// LANGS:end

/** The asset language for a locale: exact, then same base language, then English. */
export function pickLang(locale, langs = LANGS) {
  const want = String(locale || '').toLowerCase()
  const exact = langs.find((l) => l.toLowerCase() === want)
  if (exact) return exact
  const base = want.split('-')[0]
  return langs.find((l) => l.toLowerCase().split('-')[0] === base) || 'en'
}

const camel = (s) => s.replace(/-([a-z])/g, (_, c) => c.toUpperCase())

/** Writes each marked attribute from `texts` (`{ group: { key: text } }`). Never overwrites. */
export function fill(texts, root = document) {
  if (!texts || !root || !root.querySelectorAll) return
  for (const el of root.querySelectorAll('[data-i18n]')) {
    for (const a of el.attributes) {
      if (a.name !== 'data-i18n' && !a.name.startsWith('data-i18n-')) continue
      const target = a.name === 'data-i18n' ? 'labels' : camel(a.name.slice('data-i18n-'.length))
      const group = texts[a.value]
      if (group && !el.dataset[target]) el.dataset[target] = JSON.stringify(group)
    }
  }
}

let texts = null

async function load() {
  if (typeof document === 'undefined') return
  const first = document.querySelector('[data-i18n],[data-locale]')
  if (!document.querySelector('[data-i18n]')) return
  const locale = (first && first.dataset.locale) || (window.Shopify && window.Shopify.locale) || document.documentElement.lang
  try {
    const res = await fetch(new URL(`ifcvo-i18n-${pickLang(locale)}.json`, import.meta.url))
    if (res.ok) texts = await res.json()
  } catch (e) { /* English defaults */ }
  fill(texts)
  // Theme editor: a re-rendered section gets the cached texts before its script re-mounts.
  document.addEventListener('shopify:section:load', (e) => fill(texts, e.target))
}

await load()
